import{_ as s,a0 as g,w as r,s as w,ao as c,I as o,x as e,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"ReactOS 新手指南 | LCTT x X-CMD","titleTemplate":false,"description":"ReactOS 新手指南 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ReactOS 新手指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ReactOS 新手指南 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160610 Getting started with ReactOS","title":"ReactOS 新手指南","tag":"201607","desc":""},"relativePath":"201607/20160610 Getting started with ReactOS.md","filePath":"[post].md"}'),n={name:"201607/20160610 Getting started with ReactOS.md"};function m(h,t,l,d,f,S){const a=g("Link");return r(),w("div",null,[t[13]||(t[13]=c('<h1 id="reactos-新手指南" tabindex="-1">ReactOS 新手指南 <a class="header-anchor" href="#reactos-新手指南" aria-label="Permalink to “ReactOS 新手指南”">​</a></h1><p>ReactOS 是一個比較年輕的開源操作系統，它提供了一個和 Windows NT 類似的圖形界面，並且它的目標也是提供一個與 NT 功能和應用程序兼容性差不多的系統。這個項目在沒有使用任何 Unix 架構的情況下實現了一個類似 Wine 的用户模式。它的開發者們從頭實現了 NT 的架構以及對於 FAT32 的兼容，因此它也不需要負任何法律責任。這也就是説，它不是又雙叒叕一個 Linux 發行版，而是一個獨特的類 Windows 系統，並且是開源世界的一部分。這份快速指南是給那些想要一個易於使用的 Windows 的開源替代品的人準備的。</p><h3 id="安裝系統" tabindex="-1">安裝系統 <a class="header-anchor" href="#安裝系統" aria-label="Permalink to “安裝系統”">​</a></h3><p>在開始安裝這個系統之前，我需要説明一下，ReactOS 的最低硬件要求是 500MB 硬盤以及僅僅 96MB 內存。我會在一個 32 位的虛擬機裏面演示安裝過程。</p><p>現在，你需要使用箭頭鍵來選擇你想要語言，而後通過回車鍵來確認。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_1.png" alt=""></p><p>之後，再次敲擊回車鍵來繼續安裝。你也可以選擇按“R”鍵來修復現有的系統。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_2.png" alt=""></p><p>在第三屏中，你將看到一個警告説這個系統還是早期開發版本。再次敲擊回車鍵，你將看到一個需要你最後確認的配置概覽。如果你認為沒問題，就按回車。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_3.png" alt=""></p><p>然後，我們就到了分區這一步，在這裏，你可以使用“D”鍵刪除高亮分區，分別使用“P”鍵、“E”鍵以及“L”鍵來添加一個主分區、拓展分區或邏輯分區。如果你想要自己添加一個分區，你需要輸入這個分區的大小（以 MB 為單位），然後通過回車來確認。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_4.png" alt=""></p><p>但是，如果你有未使用的硬盤空間，在分區過程直接敲擊回車鍵可以自動在你選中的分區上安裝 ReactOS。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_5.png" alt=""></p><p>下一步是選擇分區的格式，不過現在我們只能選擇 FAT32。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_6.png" alt=""></p><p>再下一步是選擇安裝文件夾。我就使用默認的“/ReactOS”了，應該沒有問題。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_7.png" alt=""></p><p>然後就是等待...</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_8.png" alt=""></p><p>最後，我們要選擇啓動程序的安裝位置。如果你是在實機上操作的話，第一個選項應該是最安全的。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_9.png" alt=""></p><p>總地來説，我認為 ReactOS 的安裝嚮導很直接。儘管安裝程序的界面可能看起來一點也不現代、不友好，但是大多數情況下作為用户的我們只需要狂敲回車就能安個差不多。這就是説，ReactOS 的開發版安裝起來也是相對簡單方便的。</p><h3 id="設置-reactos" tabindex="-1">設置 ReactOS <a class="header-anchor" href="#設置-reactos" aria-label="Permalink to “設置 ReactOS”">​</a></h3><p>在我們重啓進入新系統之後，“設置嚮導”會幫助你設置系統。目前，這個嚮導僅支持設置語言和鍵盤格式。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_10.png" alt=""></p><p>我在這裏選擇了第二個鍵盤格式。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_11.png" alt=""></p><p>我還可以設置一個改變鍵盤佈局的快捷鍵。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_12.png" alt=""></p><p>之後我添加了用户名…</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_13.png" alt=""></p><p>…以及管理員密碼…</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_14.png" alt=""></p><p>在設置好時間之後，我們就算完成了系統設置。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_15.png" alt=""></p><h3 id="reactos-之內" tabindex="-1">ReactOS 之內 <a class="header-anchor" href="#reactos-之內" aria-label="Permalink to “ReactOS 之內”">​</a></h3><p>當我們歷經千辛萬苦，終於首次進入 ReactOS 的界面時，系統會檢測硬件並自動幫助我們安裝驅動。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_16.png" alt=""></p><p>這是我這裏被自動檢測出來的三個硬件：</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_17.png" alt=""></p><p>在上一張圖片裏你看到的是 ReactOS 的“應用管理器”，這東西是 Linux 的標配。不過你不會在這裏找到任何與 Linux 有關係的東西。只有在這個系統裏工作良好的開源軟件才會在這個管理器中出現。這就導致了管理器中有的分類下擠得滿滿當當，有的卻冷清異常。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_18.png" alt=""></p><p>我試着通過軟件中心安裝了 Firefox 以及通過直接下載 exe 文件雙擊安裝 Notepad++。這兩個應用都能完美運行：它們的圖標出現在了桌面上，在菜單中也出現了它們的名字，Notepad++ 也出現在了軟件中心右側的分類欄裏。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_19.png" alt=""></p><p>我沒有嘗試運行任何現代的 Windows 遊戲，如果你想配置 Direct 3D 的話，你可以轉到 “我的電腦/控制選項/WineD3D 配置”。在那裏，你能看到很多 Direct3D 選項，大致與 dx 8 的選項類似。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_20.png" alt=""></p><p>ReactOS 還有一個好的地方，就是我們可以通過“我的電腦”來操作註冊表。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_21.png" alt=""></p><p>如果你需要一個簡單點的工具，你可以在應用菜單裏打開註冊表編輯器。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_22.png" alt=""></p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_23.png" alt=""></p><p>最後，如果你認為 ReactOS 看起來有點過時了的話，你可以在桌面右擊選擇“屬性”，之後在“外觀”那裏選擇你喜歡的主題和顏色。</p><p><img src="https://www.howtoforge.com/images/getting-started-with-eeactos/pic_24.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>老實説，我對 ReactOS 的工作方式印象深刻。它相當穩定、連貫、快速，並且真正人性化。拋開 Windows 的陰影（過時的應用菜單，不合理的菜單結構）不談的話，ReactOS 幾乎做到了盡善盡美。它可能不會有太多應用可供選擇，現有的功能也可能不夠強大，但是我確信它將會繁榮壯大。關於它的數據顯示出了它的人氣，我確定將要圍繞它建立起來的社區將會很快就壯大到能把這個項目帶往成功之路的地步。如今，ReactOS 的最新版本是 0.4.1。如果想要以開源的方式運行 Windows 的應用，那麼它就是你的菜！</p><hr>',57)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),p(a,{href:"https://www.howtoforge.com/tutorial/getting-started-with-reactos/"},{default:i(()=>[...t[0]||(t[0]=[e("https://www.howtoforge.com/tutorial/getting-started-with-reactos/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),p(a,{href:"https://www.howtoforge.com/tutorial/getting-started-with-reactos/"},{default:i(()=>[...t[2]||(t[2]=[e("Bill Toulas",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),p(a,{href:"https://github.com/name1e5s"},{default:i(()=>[...t[3]||(t[3]=[e("name1e5s",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),p(a,{href:"https://github.com/PurlingNayuki"},{default:i(()=>[...t[4]||(t[4]=[e("PurlingNayuki",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const O=s(n,[["render",m]]);export{R as __pageData,O as default};
